WITH valid_subscriptions AS (SELECT *, INITCAP(TRIM(plan)) plan_title FROM subscriptions WHERE start_date BETWEEN '2023-06-07' AND '2024-06-08'), subscriptions_stats AS (SELECT CASE WHEN monthly_fee >= 238 THEN 'high' WHEN monthly_fee >= 79 THEN 'mid' ELSE 'low' END monthly_fee_bucket, plan, COUNT(*) subscription_count FROM valid_subscriptions GROUP BY CASE WHEN monthly_fee >= 238 THEN 'high' WHEN monthly_fee >= 79 THEN 'mid' ELSE 'low' END, plan) SELECT * FROM subscriptions_stats ORDER BY subscription_count, plan;
